mapper.select:
SELECT *
FROM TB_FILE
WHERE PK_ID = #{pkId}
  AND MENU_CD = #{menuCd}
ORDER BY REG_DT DESC

SELECT *
FROM TB_FILE
WHERE FILE_ID = #{fileId}
  AND MENU_CD = #{menuCd}
  AND PK_ID = #{pkId}
ORDER BY REG_DT DESC

mapper.insert:
INSERT INTO TB_FILE
( PK_ID
, FILE_DV_CD
, MENU_CD
, FILE_NEW_NAME
, FILE_NAME
, FILE_SIZE
, FILE_PATH
, FILE_TYPE
, FILE_EXTENSION
, REG_ID
, REG_DT)
VALUES ( #{pkId}
	   , #{fileDvCd}
       , #{menuCd}
       , #{fileNewName}
       , #{fileName}
       , #{fileSize}
       , #{filePath}
       , #{fileType}
       , #{fileExtension}
       , #{regId}
       , now())

mapper.delete:
DELETE FROM
    TB_FILE
WHERE 
	PK_ID = #{pkId}

AND 
	MENU_CD = #{menuCd}
